import{_ as o,l as s,o as e,c as i,v as t,p as n,x as r,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const R=JSON.parse('{"title":"复制状态机","description":"","frontmatter":{"title":"复制状态机","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/replicated-state-machine.md","filePath":"cs/replicated-state-machine.md","lastUpdated":1789023840000}'),h={name:"cs/replicated-state-machine.md"};function _(m,a,A,S,u,E){const l=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="复制状态机" tabindex="-1">复制状态机 <a class="header-anchor" href="#复制状态机" aria-label="Permalink to &quot;复制状态机&quot;">​</a></h1><div class="epigraph"><p>确定性状态机 + 同一输入日志 ⇒ 同一状态。共识的任务是复制那条日志，不是复制内存字节。</p><footer>—— 据 Schneider, Implementing Fault-Tolerant Services Using the State Machine Approach, CSUR 1990 整理</footer></div><p>上一课<a href="/cs/session-guarantees">会话保证</a>仍允许全局分叉。缺口是<strong>所有客户端看见同一操作序</strong>：锁、配置、事务提交需要这个。本课钉 Schneider 的状态机方法，把前面的线性一致对象还原成「日志上的确定性 apply」。后课 Paxos 才说日志怎么达成。不重写 CRDT 半格。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>副本各自有状态 \\(s\\)，操作 \\(o\\) 是确定性的：\\(s&#39;=\\delta(s,o)\\)。若所有正确副本 apply 同一序列 \\(o_1,o_2,\\ldots\\)，则状态永远相等。故障：崩溃停副本落后，追上日志即可。缺口从「复制状态」变成「复制输入序」——带宽与语义都更干净，因为状态可能很大，操作很小。</p><p>非确定性（时间、随机、线程调度）必须赶出 \\(\\delta\\)：把随机数当输入放进日志，而不是各机自抽。这是实现 RSM 最常见的破法。</p><p><span class="marginnote">Schneider 1990 综述把 Lamport 时间、共识、拜占庭都接到状态机框架。主备传状态是另一方法，上单元已讲。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三件套：共识模块输出已提交前缀；状态机按前缀 apply；客户端把请求交给共识（或领导者）。快照把前缀压缩成状态，截断日志——后课 Raft 快照。读：跟日志提交点走则线性一致；读落后副本则掉档。</p>',9)),(e(),n(c,null,{default:r(()=>[d(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20LR%0A%20%20REQ%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20LOG%5B%22%E5%85%B1%E8%AF%86%E6%97%A5%E5%BF%97%22%5D%0A%20%20LOG%20--%3E%20APP%5B%22%E7%A1%AE%E5%AE%9A%E6%80%A7%20apply%22%5D%0A%20%20APP%20--%3E%20S%5B%22%E5%89%AF%E6%9C%AC%E7%8A%B6%E6%80%81%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与寄存器 quorum：RSM 给的是操作的全序，能实现任意对象，不只是读写寄存器。与 CRDT：RSM 协调贵、语义任意；CRDT 无协调、语义受限。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>线性化点：通常在日志提交（多数派持久）处，apply 必须在返回前完成，或返回的索引对后续读可见。Raft 的 read index、lease read 是优化，不改这一定义。</p><p>拜占庭 RSM 要求确定性<strong>且</strong>不能让叛徒提交两条日志——那是 PBFT。崩溃 RSM 用 Paxos/Raft/VR。本课故障类仍默认崩溃停或崩溃恢复（日志在盘上）。</p><p>本课不把 Kubernetes 控制器当 RSM 证明：调和循环是最终一致。也不把 WAL 单机恢复当成分布式日志共识。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 prepare/accept 消息，不引入成员变更。后课默认：要线性一致任意对象，用 RSM；日志的共识算法从 Paxos 讲起。主备是状态转移特例，链是提交点特例，都不是任意 \\(\\delta\\) 的通用解。</p><p>输入序是唯一需要共识的东西。状态是推论。下一课开始付共识的消息税。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RSM：同一确定性 \\(\\delta\\) + 同一已提交日志。</li><li>非确定性必须进日志，不能进 \\(\\delta\\)。</li><li>读的一致性档取决于读到哪条提交前缀。</li><li>出处：Schneider, CSUR 1990。</li></ul>',10))])}const P=o(h,[["render",_]]);export{R as __pageData,P as default};
